import itertools
from collections import Counter


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    start_state = (data["source"], initial_mask, 0)
    best = {start_state: start}
    queue = [(start, *start_state)]
    coupons = data["coupons"]
    deadline = data["deadline"]

    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != time:
            continue
        if node == data["target"] and mask == full and (
                coupon_rule == "at_most" or used == coupons):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > deadline:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, *next_state))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        quotient, remainder = divmod(numerator, 10000)
        if mode == "half_up" and remainder >= 5000:
            quotient += 1
        return quotient

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    versions = {name: {row["version"]: row for row in rows}
                for name, rows in packages.items()}
    options = [[-1] + sorted(versions[name]) for name in names]
    best_vector = None
    best_result = None

    for choice in itertools.product(*options):
        selected = {name: version for name, version in zip(names, choice)
                    if version != -1}
        if any(name not in selected or
               not low <= selected[name] <= high
               for name, (low, high) in roots.items()):
            continue
        if any(version in blocked.get(name, [])
               for name, version in selected.items()):
            continue
        if any(name in selected and selected[name] != version
               for name, version in pins.items()):
            continue

        edges = {name: [] for name in selected}
        valid = True
        for name, version in selected.items():
            row = versions[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = selected.get(target)
                if (target_version is None or
                        not dep["min"] <= target_version <= dep["max"]):
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(selected):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in selected):
            continue
        vector = tuple(selected.get(name, -1) for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_result = selected

    if best_result is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_result}


def _intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [job for job in jobs if job["id"] not in blocked]
    if not mandatory.issubset({job["id"] for job in available}):
        return {"error": "impossible"}
    best_value = None
    best_ids = None

    for subset in itertools.combinations(available, k):
        ids = [job["id"] for job in subset]
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in subset)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in subset:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        fits = True
        for _, delta in sorted(events):
            active += delta
            if active > 2:
                fits = False
                break
        if not fits:
            continue
        value = sum(job["value"] for job in subset)
        sorted_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids < best_ids)):
            best_value = value
            best_ids = sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


SOLVERS = {
    "component_01": lambda data: _route(data, "exact", 2),
    "component_02": lambda data: _route(data, "at_most", 1),
    "component_03": lambda data: _route(data, "exact", 1),
    "component_04": lambda data: _route(data, "at_most", 2),
